package com.auditcli.http

import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.OutputStream
import java.net.Socket
import java.nio.charset.StandardCharsets
import java.time.Instant
import java.io.File

data class AuditEntry(val timestamp: String, val method: String, val path: String, val status: Int)

class AuditLogger(private val logFile: File) {
    fun log(entry: AuditEntry) {
        logFile.appendText("${entry.timestamp} ${entry.method} ${entry.path} ${entry.status}\n")
    }
}

class HttpRequestBuilder {
    private var method: String = "GET"
    private var path: String = "/"
    private var host: String = "localhost"
    private var headers: MutableMap<String, String> = mutableMapOf()
    private var body: String? = null

    fun method(m: String) = apply { this.method = m }
    fun path(p: String) = apply { this.path = p }
    fun host(h: String) = apply { this.host = h }
    fun header(key: String, value: String) = apply { this.headers[key] = value }
    fun body(b: String?) = apply { this.body = b }

    fun build(): ByteArray {
        val sb = StringBuilder()
        sb.append("$method $path HTTP/1.1\r\n")
        sb.append("Host: $host\r\n")

        if (body != null) {
            val bodyBytes = body!!.toByteArray(StandardCharsets.UTF_8)
            // Set Content-Length based on actual byte length for correctness
            headers.putIfAbsent("Content-Length", bodyBytes.size.toString())
            headers.remove("Transfer-Encoding")
        }

        for ((key, value) in headers) {
            sb.append("$key: $value\r\n")
        }
        sb.append("\r\n")

        if (body != null) {
            sb.append(body)
        }
        return sb.toString().toByteArray(StandardCharsets.UTF_8)
    }
}

class ProxyClient(
    private val targetHost: String,
    private val targetPort: Int,
    private val auditLogger: AuditLogger
) {
    fun forwardRequest(userInput: Map<String, String>): String {
        val method = sanitizeMethod(userInput["method"] ?: "GET")
        val path = sanitizePath(userInput["path"] ?: "/")
        val extraHeaders = parseUserHeaders(userInput["headers"] ?: "")
        val body = userInput["body"]

        val builder = HttpRequestBuilder()
            .method(method)
            .path(path)
            .host(targetHost)

        for ((key, value) in extraHeaders) {
            builder.header(key, value)
        }

        if (body != null && body.isNotEmpty()) {
            builder.body(body)
        }

        val rawRequest = builder.build()
        val response = sendRaw(rawRequest)
        val statusCode = extractStatusCode(response)

        auditLogger.log(AuditEntry(
            timestamp = Instant.now().toString(),
            method = method,
            path = path,
            status = statusCode
        ))

        return response
    }

    private fun sanitizeMethod(method: String): String {
        val allowed = setOf("GET", "POST", "PUT", "DELETE", "PATCH")
        val upper = method.uppercase().trim()
        return if (upper in allowed) upper else "GET"
    }

    private fun sanitizePath(path: String): String {
        // Remove any CR/LF to prevent header injection in request line
        return path.replace("\r", "").replace("\n", "").let {
            if (it.startsWith("/")) it else "/$it"
        }
    }

    private fun parseUserHeaders(raw: String): Map<String, String> {
        val result = mutableMapOf<String, String>()
        if (raw.isBlank()) return result

        // Only allow well-formed header token characters in keys (RFC 7230 token)
        val validKeyRegex = Regex("^[A-Za-z0-9!#\$%&'*+.^_`|~-]+$")

        // Headers provided as semicolon-separated key=value pairs
        raw.split(";").forEach { pair ->
            val parts = pair.split("=", limit = 2)
            if (parts.size == 2) {
                val key = parts[0].trim()
                val value = parts[1].trim()
                // Block dangerous headers including transfer-encoding
                val blocked = setOf("host", "content-length", "transfer-encoding")
                if (key.lowercase() !in blocked && 
                    validKeyRegex.matches(key) &&
                    !key.contains("\r") && !key.contains("\n") &&
                    !value.contains("\r") && !value.contains("\n")) {
                    result[key] = value
                }
            }
        }
        return result
    }

    private fun sendRaw(request: ByteArray): String {
        Socket(targetHost, targetPort).use { socket ->
            val out: OutputStream = socket.getOutputStream()
            out.write(request)
            out.flush()

            val reader = BufferedReader(InputStreamReader(socket.getInputStream()))
            val response = StringBuilder()
            var line: String?
            socket.soTimeout = 5000
            try {
                while (reader.readLine().also { line = it } != null) {
                    response.append(line).append("\n")
                }
            } catch (e: Exception) {
                // timeout or connection closed
            }
            return response.toString()
        }
    }

    private fun extractStatusCode(response: String): Int {
        val firstLine = response.lines().firstOrNull() ?: return 0
        val parts = firstLine.split(" ")
        return if (parts.size >= 2) parts[1].toIntOrNull() ?: 0 else 0
    }
}

fun main(args: Array<String>) {
    val logFile = File(System.getProperty("audit.log", "/var/log/audit-proxy.log"))
    val logger = AuditLogger(logFile)
    val host = System.getProperty("target.host", "backend.internal")
    val port = System.getProperty("target.port", "80").toInt()

    val client = ProxyClient(host, port, logger)

    // CLI interface: read commands from stdin
    val reader = BufferedReader(InputStreamReader(System.`in`))
    println("Audit Proxy CLI ready. Enter requests as method|path|headers|body")

    while (true) {
        print("> ")
        val line = reader.readLine() ?: break
        if (line == "quit") break

        val parts = line.split("|", limit = 4)
        val input = mapOf(
            "method" to (parts.getOrNull(0) ?: "GET"),
            "path" to (parts.getOrNull(1) ?: "/"),
            "headers" to (parts.getOrNull(2) ?: ""),
            "body" to (parts.getOrNull(3) ?: "")
        )

        try {
            val response = client.forwardRequest(input)
            println(response)
        } catch (e: Exception) {
            println("Error: ${e.message}")
        }
    }
}
